Lemma ACONST_layout_poison : forall m, ACONST m ->
  rw_cells bsegs m ACANPOISON_CELL [C1 (b8 1)] /\ rw_cells bsegs m AGOT_MEMSETP [C8 (wz AMEMSETP_CELL)] /\
  rw_cells bsegs m AMEMSETP_CELL [C8 (wz AREAL_MEMSET)] /\ rw_cells bsegs m AGOT_CFLAGS [C8 (wz 0x1bf2e8)].
